function toast(t='Saved ✓'){let e=document.querySelector('.wr18-toast');if(!e){e=document.createElement('div');e.className='wr18-toast';document.body.appendChild(e)}e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1400)}
const roots=()=>S.cargo.filter(x=>!x.parent_id),children=id=>S.cargo.filter(x=>x.parent_id===id),party=r=>S.parties.find(x=>String(x.role||'').toLowerCase()===r);
const entity=id=>S.entities.find(x=>x.id===id),exactEntity=v=>{const s=String(v||'').trim().toLowerCase();return S.entities.find(x=>String(x.name||'').toLowerCase()===s||String(x.code||'').toLowerCase()===s)||null};
const customerEntity=()=>entity(S.job?.customer_id),customerName=()=>customerEntity()?.name||'Unidentified customer';
const addresses=id=>S.addresses.filter(x=>x.entity_id===id&&x.active!==false),contacts=id=>S.contacts.filter(x=>x.entity_id===id&&x.active!==false);
const primaryAddress=id=>addresses(id).find(x=>x.is_primary)||addresses(id)[0],primaryContact=id=>contacts(id).find(x=>x.is_primary)||contacts(id)[0];
function addressText(a){return a?[a.line1,a.line2,[a.city,a.state_region,a.postal_code].filter(Boolean).join(' '),a.country_code].filter(Boolean).join(', '):'No address saved'}
const workflow=()=>[...(S.workflow?.steps||FALLBACK)].filter(x=>x.enabled!==false&&x.key!=='identify_expected').sort((a,b)=>(a.order||0)-(b.order||0));
const skipped=k=>S.events.some(e=>e.event_type==='STEP_SKIPPED'&&e.event_data?.step_key===k);
function done(s){const v=S.visit||{},r=roots();switch(s.key){case'check_in':return!!v.time_in;case'verify_driver':return!!v.driver_id_verified;case'start_unload':return!!v.operation_started_at;case'finish_unload':return!!v.operation_completed_at;case'release_driver':return!!v.time_out;case'parties':return!!S.job?.customer_id&&!!party('shipper')&&!!party('consignee');case'receive_cargo':return r.length>0&&r.every(x=>x.processing_status==='processed');case'documents':return S.docs.length>0||skipped(s.key);case'compliance':return S.controls.length===0||S.controls.every(x=>x.verified||['complete','cleared','released'].includes(String(x.status||'').toLowerCase()))||skipped(s.key);case'putaway':return r.length>0&&r.every(x=>x.current_location_id||x.warehouse_location_id);case'complete':return!!S.wr.completed_at;case'notify_customer':return S.events.some(e=>e.event_type==='CUSTOMER_NOTIFIED')||skipped(s.key);default:return S.events.some(e=>e.event_type==='STEP_COMPLETED'&&e.event_data?.step_key===s.key)||skipped(s.key)}}
const current=()=>workflow().find(x=>!done(x))||workflow().at(-1);
function missing(){const m=[];if(!S.job?.customer_id)m.push('Customer');if(!party('shipper'))m.push('Shipper');if(!party('consignee'))m.push('Consignee');if(!roots().length)m.push('Cargo');if(S.visit?.time_in&&!S.visit?.time_out)m.push('Driver on site');if(roots().some(x=>!(x.current_location_id||x.warehouse_location_id)))m.push('Put-away');if(S.flags.length)m.push(`${S.flags.length} exception${S.flags.length===1?'':'s'}`);if(S.controls.some(x=>!x.verified&&!['complete','cleared','released'].includes(String(x.status||'').toLowerCase())))m.push('Compliance');return m}
function summary(){const r=roots();return{expected:S.visit?.unload_expected_qty,unloaded:S.visit?.unload_actual_qty,processed:r.filter(x=>x.processing_status==='processed').reduce((a,x)=>a+Number(x.quantity||0),0),putaway:r.filter(x=>x.current_location_id||x.warehouse_location_id).reduce((a,x)=>a+Number(x.quantity||0),0),exceptions:S.flags.length,missing:missing().length}}
function completion(){const w=workflow(),n=w.filter(done).length;return{n,total:w.length,pct:w.length?Math.round(n/w.length*100):0}}
async function userId(){const{data}=await supabase.auth.getUser();return data?.user?.id||null}
async function event(type,data={}){await supabase.from('workflow_events').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,warehouse_receipt_id:S.wr.id,event_type:type,event_data:data,actor_id:await userId()})}

async function load(id){const{data:wr,error}=await supabase.from('warehouse_receipts').select('*').eq('id',id).single();if(error)throw error;const [job,visit,cargo,parties,entities,docs,flags,controls,wf,events,locs]=await Promise.all([
 supabase.from('jobs').select('*').eq('id',wr.job_id).maybeSingle(),supabase.from('warehouse_visits').select('*').eq('warehouse_receipt_id',id).eq('direction','inbound').order('created_at',{ascending:false}).limit(1),supabase.from('cargo_units').select('*').eq('job_id',wr.job_id).order('created_at'),supabase.from('warehouse_receipt_parties').select('*').eq('warehouse_receipt_id',id),supabase.from('entities').select('id,name,code,roles,email,phone').eq('organization_id',wr.organization_id).order('name').limit(2500),supabase.from('documents').select('*').eq('warehouse_receipt_id',id).eq('is_current',true).order('created_at',{ascending:false}),supabase.from('operational_flags').select('*').eq('warehouse_receipt_id',id).eq('active',true).order('created_at',{ascending:false}),supabase.from('receiving_controls').select('*').eq('warehouse_receipt_id',id).order('created_at',{ascending:false}),supabase.from('workflow_definitions').select('*').eq('organization_id',wr.organization_id).eq('transaction_type','WAREHOUSE_RECEIPT').eq('is_active',true).order('version',{ascending:false}).limit(1),supabase.from('workflow_events').select('*').eq('warehouse_receipt_id',id).order('created_at'),supabase.from('warehouse_locations').select('id,code,name').eq('organization_id',wr.organization_id).eq('active',true).order('code')]);
 const entityIds=[...(entities.data||[]).map(x=>x.id)];let add=[],con=[];if(entityIds.length){const[a,c]=await Promise.all([supabase.from('entity_addresses').select('*').in('entity_id',entityIds).eq('active',true),supabase.from('entity_contacts').select('*').in('entity_id',entityIds).eq('active',true)]);add=a.data||[];con=c.data||[]}
 S={wr,job:job.data||{},visit:visit.data?.[0]||null,cargo:cargo.data||[],parties:parties.data||[],entities:entities.data||[],addresses:add,contacts:con,docs:docs.data||[],flags:flags.data||[],controls:controls.data||[],workflow:wf.data?.[0]||null,events:events.data||[],locations:locs.data||[]};return S}
async function refresh(){if(wrId)await load(wrId)}

function head(){const s=summary(),c=completion();return `<header class="wr18-head"><div class="wr18-headtop"><div><div class="wr18-k">Warehouse receipt</div><div class="wr18-num">${esc(S.wr.receipt_number)}</div><div class="wr18-sub">${esc(customerName())} · Created ${fmt(S.wr.created_at)}${S.wr.received_at?` · Received ${fmt(S.wr.received_at)}`:''}</div></div><span class="wr18-state">${esc(S.wr.status)}</span></div><div class="wr18-row"><div class="wr18-switch"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided</button><button data-mode="record" class="${mode==='record'?'active':''}">Record</button></div><div class="wr18-tools"><button data-out="pdf">WR PDF</button><button data-out="4x6">4×6</button><button data-out="2x1">2×1</button><button data-doc-scan>${scanIcon} Scan doc</button><button data-doc-upload>${docIcon} Upload</button></div></div><div class="wr18-summary"><div class="wr18-stat"><small>Expected</small><b>${s.expected??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr18-stat"><small>Unloaded</small><b>${s.unloaded??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr18-stat"><small>Processed</small><b>${s.processed}</b></div><div class="wr18-stat"><small>Put away</small><b>${s.putaway}</b></div><div class="wr18-stat"><small>Exceptions</small><b>${s.exceptions}</b></div><div class="wr18-stat"><small>Missing</small><b>${s.missing}</b></div></div><div class="wr18-meter"><span style="width:${c.pct}%"></span></div></header>`}
function timeline(){const v=S.visit||{},a=[['Checked in',v.time_in],['ID verified',v.driver_id_verified_at],['Unload started',v.operation_started_at],['Unload finished',v.operation_completed_at],['Released',v.time_out]];return `<div class="wr18-timeline">${a.map(([l,t])=>`<div class="wr18-event ${t?'done':''}"><small>${l}</small><b>${t?'✓ '+tm(t):'Pending'}</b></div>`).join('')}</div>`}
function progress(){const w=workflow(),cur=current();return `<div class="wr18-progress">${w.map(x=>`<span class="${done(x)?'done':x.key===cur?.key?'now':''}">${done(x)?'✓ ':''}${esc(x.label)}${x.required===false?' · optional':''}</span>`).join('')}</div>`}
function datalist(){return `<datalist id="wr18-entities">${S.entities.map(x=>`<option value="${esc(x.name)}">${esc(x.code||'')}</option>`).join('')}</datalist>`}

function guided(){const s=current();return `<div class="wr18-guide"><section class="wr18-panel">${progress()}<div class="wr18-now">RIGHT NOW · ${workflow().findIndex(x=>x.key===s.key)+1} OF ${workflow().length}</div><h1 class="wr18-title">${esc(s.label)}</h1><div class="wr18-copy">${stepCopy(s.key)}</div>${timeline()}${guidedTask(s)}</section></div>`}
function stepCopy(k){return({check_in:'Capture only what is needed to establish the dock visit. Everything else can be added later.',verify_driver:'Capture the driver ID and record the verification.',start_unload:'Check-in is complete. Start the physical unload when custody transfer begins.',finish_unload:'Record the physical tally. Detailed cargo processing can continue after the driver leaves.',release_driver:'Close the dock visit and release the truck. Warehouse processing continues independently.',parties:'Confirm the Customer, Shipper and Consignee. The address and primary contact follow the selected entity.',receive_cargo:'Build the physical cargo exactly as it exists: handling units outside, contents inside.',documents:'Add or scan documents tied to this receipt.',compliance:'Review DG, in-bond / 7512 and FTZ controls only when applicable.',putaway:'Scan or assign each handling unit to its warehouse location.',complete:'Review what is complete, what is missing, and close the WR.',notify_customer:'Customer notification is optional unless your workflow requires it.'}[k]||'Complete this workflow step.')}
function guidedTask(s){const v=S.visit||{};switch(s.key){case'check_in':return `<div class="wr18-task"><h3>Who just arrived?</h3><div class="wr18-fields"><label class="wr18-field"><span>Carrier</span><input id="g-carrier" list="wr18-entities" value="${esc(v.carrier_name_snapshot||'')}" placeholder="Search or type"></label><label class="wr18-field"><span>Driver</span><input id="g-driver" value="${esc(v.driver_name||'')}" placeholder="Driver name"></label><label class="wr18-field"><span>Reference</span><input id="g-ref" value="${esc(v.bol_number||v.pro_number||v.tracking_number||'')}" placeholder="BOL / PRO / tracking"></label><label class="wr18-field"><span>Door</span><input id="g-door" value="${esc(v.door||'')}" placeholder="Optional"></label></div><div class="wr18-actions"><button class="wr18-primary" data-g-checkin>Check in</button><button class="wr18-secondary" data-scan-ref>${scanIcon} Scan reference</button></div></div>`;case'verify_driver':return `<div class="wr18-task"><h3>Identity verification</h3><div class="wr18-actions"><button class="wr18-primary" data-id-upload>${docIcon} Capture / upload ID</button></div><label class="wr18-check"><input id="g-verify" type="checkbox"><span>I verified a government-issued photo ID and confirmed it matches the driver presenting the freight.</span></label><div class="wr18-actions"><button class="wr18-primary" data-g-verify>Confirm verification</button></div></div>`;case'start_unload':return `<div class="wr18-task"><h3>Ready to unload</h3><div class="wr18-actions"><button class="wr18-primary" data-g-start>Start unloading</button></div></div>`;case'finish_unload':return `<div class="wr18-task"><h3>Unload & tally</h3><div class="wr18-fields"><label class="wr18-field"><span>Expected</span><input id="g-exp" type="number" step="any" value="${esc(v.unload_expected_qty??'')}"></label><label class="wr18-field"><span>Actual unloaded</span><input id="g-act" type="number" step="any" value="${esc(v.unload_actual_qty??'')}"></label><label class="wr18-field"><span>UOM</span><select id="g-uom">${['PLT','CTN','BOX','CRT','DRM','EA'].map(x=>`<option ${x===(v.unload_uom||'PLT')?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="wr18-actions"><button class="wr18-primary" data-g-finish>Finish unloading</button></div></div>`;case'release_driver':return `<div class="wr18-task"><h3>Release the driver</h3><div class="wr18-actions"><button class="wr18-primary" data-g-release>Release driver</button></div></div>`;case'parties':return `<div class="wr18-task"><h3>Parties</h3><div class="wr18-fields"><label class="wr18-field"><span>Customer</span><input id="g-customer" list="wr18-entities" value="${esc(customerName()==='Unidentified customer'?'':customerName())}" placeholder="Search or type"></label><label class="wr18-field"><span>Shipper</span><input id="g-shipper" list="wr18-entities" value="${esc(party('shipper')?.display_name||'')}" placeholder="Search or type"></label><label class="wr18-field"><span>Consignee</span><input id="g-consignee" list="wr18-entities" value="${esc(party('consignee')?.display_name||'')}" placeholder="Search or type"></label></div><div class="wr18-actions"><button class="wr18-primary" data-g-parties>Save & continue</button></div></div>`;case'receive_cargo':return `<div class="wr18-task">${cargoWorkspace(true)}</div>`;case'documents':return `<div class="wr18-task"><h3>Documents</h3>${documentsBlock()}<div class="wr18-actions"><button class="wr18-primary" data-doc-upload>Upload document</button><button class="wr18-secondary" data-doc-scan>Scan document</button>${s.required===false?'<button class="wr18-secondary" data-skip="documents">Skip optional step</button>':''}</div></div>`;case'compliance':return `<div class="wr18-task"><h3>Compliance</h3>${complianceBlock()}${s.required===false?'<div class="wr18-actions"><button class="wr18-secondary" data-skip="compliance">Not applicable / continue</button></div>':''}</div>`;case'putaway':return `<div class="wr18-task"><h3>Put away</h3>${putawayBlock()}</div>`;case'complete':return `<div class="wr18-task"><h3>Review & complete</h3>${missing().length?`<div class="wr18-missing">Missing: ${esc(missing().join(' · '))}</div>`:'<div class="wr18-good">Ready to complete.</div>'}<div class="wr18-actions"><button class="wr18-primary" data-g-complete>Complete WR</button></div></div>`;case'notify_customer':return `<div class="wr18-task"><h3>Customer notification</h3><p>Record the notification after you send the WR/POD using your customer communication channel.</p><div class="wr18-actions"><button class="wr18-primary" data-g-notify>Mark customer notified</button>${s.required===false?'<button class="wr18-secondary" data-skip="notify_customer">Skip</button>':''}</div></div>`;default:return `<div class="wr18-task"><h3>${esc(s.label)}</h3><div class="wr18-actions"><button class="wr18-primary" data-g-generic="${esc(s.key)}">Mark complete</button>${s.required===false?`<button class="wr18-secondary" data-skip="${esc(s.key)}">Skip</button>`:''}</div></div>`}}

function tabs(){const T=[['overview','Overview'],['parties','Parties'],['arrival','Arrival'],['cargo','Cargo'],['documents','Documents'],['compliance','Compliance'],['exceptions','Exceptions'],['activity','Activity']];return `<nav class="wr18-tabs">${T.map(([k,l])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</nav>`}
function record(){return `${tabs()}<div class="wr18-content"><section class="wr18-panel">${recordTab()}</section></div>`}
function recordTab(){switch(tab){case'overview':return overview();case'parties':return partiesView();case'arrival':return arrivalView();case'cargo':return cargoWorkspace(false);case'documents':return `<div class="wr18-card"><h3>Documents</h3>${documentsBlock()}<div class="wr18-actions"><button class="wr18-primary" data-doc-upload>Upload</button><button class="wr18-secondary" data-doc-scan>Scan document</button></div></div>`;case'compliance':return `<div class="wr18-card"><h3>Compliance</h3>${complianceBlock()}</div>`;case'exceptions':return `<div class="wr18-card"><h3>Exceptions</h3><div class="wr18-list">${S.flags.length?S.flags.map(x=>`<div class="wr18-line"><h4>${esc(x.flag_type)}</h4><small>${esc(x.severity||'')} · ${fmt(x.created_at)}</small></div>`).join(''):'<div class="wr18-good">No active exceptions.</div>'}</div></div>`;case'activity':return activityView();default:return overview()}}
function overview(){const c=completion();return `<div class="wr18-grid"><div class="wr18-card"><h3>Receipt overview</h3><div class="wr18-list"><div class="wr18-line"><h4>${esc(S.wr.receipt_number)}</h4><small>Created ${fmt(S.wr.created_at)} · Received ${fmt(S.wr.received_at)} · ${esc(S.wr.status)}</small></div><div class="wr18-line"><h4>${esc(customerName())}</h4><small>Customer</small></div><div class="wr18-line"><h4>${esc(party('shipper')?.display_name||'Shipper missing')}</h4><small>Shipper</small></div><div class="wr18-line"><h4>${esc(party('consignee')?.display_name||'Consignee missing')}</h4><small>Consignee</small></div></div>${missing().length?`<div class="wr18-missing">Needs attention: ${esc(missing().join(' · '))}</div>`:'<div class="wr18-good">Receipt is operationally complete.</div>'}</div><div class="wr18-card"><h3>Progress</h3><div class="wr18-title" style="font-size:32px">${c.pct}%</div><p>${c.n} of ${c.total} workflow steps complete.</p><div class="wr18-meter"><span style="width:${c.pct}%"></span></div><div class="wr18-actions"><button class="wr18-secondary" data-open-workflow>Edit workflow</button></div></div></div>`}
function partyCard(role,label,id){const p=role==='customer'?customerEntity():entity(party(role)?.entity_id),name=role==='customer'?customerName():(party(role)?.display_name||'Not set'),a=p?primaryAddress(p.id):null,c=p?primaryContact(p.id):null,more=p?addresses(p.id).filter(x=>x.id!==a?.id):[];return `<article class="wr18-party" data-partycard="${role}"><div class="wr18-partyhead"><div><div class="wr18-partyrole">${label}</div><div class="wr18-partyname">${esc(name)}</div></div><button data-party-edit="${role}">Edit</button></div><div class="wr18-partyaddr">${esc(addressText(a))}</div>${c?`<div class="wr18-partycontact">${esc(c.name||'Primary contact')}${c.phone?` · ${esc(c.phone)}`:''}${c.email?`<br>${esc(c.email)}`:''}</div>`:''}${more.length?`<button data-party-more="${role}" style="margin-top:8px">${more.length} more address${more.length===1?'':'es'} ▾</button><div class="wr18-address-more">${more.map(x=>`<div class="wr18-partyaddr">${esc(x.name||x.address_type||'Address')}: ${esc(addressText(x))}</div>`).join('')}</div>`:''}</article>`}
function partiesView(){return `<div class="wr18-card"><h3>Parties</h3><p>Entity master data stays compact here; addresses and primary contacts follow the selected party automatically.</p><div class="wr18-partygrid" style="margin-top:14px">${partyCard('customer','Customer')}${partyCard('shipper','Shipper')}${partyCard('consignee','Consignee')}</div></div>`}
function arrivalView(){const v=S.visit||{};return `<div class="wr18-grid"><div class="wr18-card"><h3>Dock visit</h3>${timeline()}<div class="wr18-fields"><label class="wr18-field"><span>Carrier</span><input id="r-carrier" list="wr18-entities" value="${esc(v.carrier_name_snapshot||'')}"></label><label class="wr18-field"><span>Driver</span><input id="r-driver" value="${esc(v.driver_name||'')}"></label><label class="wr18-field"><span>BOL</span><input id="r-bol" value="${esc(v.bol_number||'')}"></label><label class="wr18-field"><span>PRO / Tracking</span><input id="r-pro" value="${esc(v.pro_number||v.tracking_number||'')}"></label><label class="wr18-field"><span>Door</span><input id="r-door" value="${esc(v.door||'')}"></label><label class="wr18-field"><span>Trailer / Seal</span><input id="r-trailer" value="${esc([v.trailer_number,v.seal_number].filter(Boolean).join(' / '))}"></label></div><div class="wr18-actions"><button class="wr18-primary" data-r-arrival>Save arrival</button></div></div><div class="wr18-card"><h3>Unload</h3><div class="wr18-list"><div class="wr18-line"><h4>${esc(v.unload_expected_qty??'—')} ${esc(v.unload_uom||'')}</h4><small>Expected</small></div><div class="wr18-line"><h4>${esc(v.unload_actual_qty??'—')} ${esc(v.unload_uom||'')}</h4><small>Actual unloaded</small></div><div class="wr18-line"><h4>${v.driver_id_verified?'Verified':'Not verified'}</h4><small>Driver ID</small></div></div></div></div>`}
function documentsBlock(){return `<div class="wr18-list">${S.docs.length?S.docs.map(d=>`<div class="wr18-line"><h4>${esc(d.display_name||d.file_name||d.category||'Document')}</h4><small>${esc(d.category||d.document_type||'')} · ${fmt(d.created_at)}</small></div>`).join(''):'<div class="wr18-missing">No documents attached yet.</div>'}</div>`}
function complianceBlock(){return `<div class="wr18-list">${S.controls.length?S.controls.map(x=>`<div class="wr18-line"><h4>${esc(x.control_type==='IN_BOND_7512'?'IN-BOND / 7512':x.control_type)}</h4><small>${esc(x.status||'pending')} · ${x.verified?'verified':'not verified'}</small></div>`).join(''):'<div class="wr18-good">No active structured controls.</div>'}</div>`}
function activityView(){const ev=[['WR created',S.wr.created_at],['Checked in',S.visit?.time_in],['ID verified',S.visit?.driver_id_verified_at],['Unload started',S.visit?.operation_started_at],['Unload finished',S.visit?.operation_completed_at],['Driver released',S.visit?.time_out],['WR completed',S.wr.completed_at]].filter(x=>x[1]);return `<div class="wr18-card"><h3>Activity</h3><div class="wr18-list">${ev.map(([l,t])=>`<div class="wr18-line"><h4>${esc(l)}</h4><small>${fmt(t)}</small></div>`).join('')}</div></div>`}
function cargoWorkspace(compact=false){return `<div class="wr18-card" style="padding:0;border:0;background:transparent"><div class="wr18-cargohead"><div><h3>Physical cargo</h3><p>Outer handling units contain inner cargo. Edit either level without losing your place.</p></div><div class="wr18-actions" style="margin:0"><button class="wr18-primary" data-cargo-add>＋ Handling unit</button></div></div>${roots().length?`<div class="wr18-tree">${roots().map(x=>nodeHTML(x,0)).join('')}</div>`:'<div class="wr18-missing">No cargo recorded yet.</div>'}</div>`}
function nodeHTML(c,depth){const kids=children(c.id),loc=S.locations.find(x=>x.id===(c.current_location_id||c.warehouse_location_id)),dim=c.length_in&&c.width_in&&c.height_in?`${c.length_in}×${c.width_in}×${c.height_in} in`:null,meta=[c.description,c.part_number&&`Part ${c.part_number}`,c.sku&&`SKU ${c.sku}`,c.weight_lb&&`${Number(c.weight_lb).toFixed(1)} lb`,dim,loc&&`@ ${loc.code}`].filter(Boolean).join(' · ');return `<div class="wr18-node ${depth?'child':''}" data-node="${c.id}"><div class="wr18-nodehead"><div><div class="wr18-nodetitle">${esc(c.quantity||0)} ${esc(c.uom||UOM[c.package_type]||'EA')} · ${esc(c.package_type||'CARGO')}</div><div class="wr18-nodemeta">${esc(meta||'No description')}</div></div><span class="wr18-state">${esc(c.processing_status||'pending')}</span></div><div class="wr18-nodeactions"><button data-cargo-edit="${c.id}">Edit</button><button data-cargo-inside="${c.id}">＋ Inside</button><button data-cargo-copy="${c.id}">Copy</button><button data-cargo-label="${c.id}">4×6</button>${depth?`<button data-cargo-mini="${c.id}">2×1</button>`:''}</div>${kids.map(k=>nodeHTML(k,depth+1)).join('')}</div>`}
function putawayBlock(){return `<div class="wr18-list">${roots().map(x=>`<div class="wr18-line"><h4>${esc(x.quantity)} ${esc(x.uom||'')} · ${esc(x.package_type||'Cargo')}</h4><div class="wr18-fields" style="margin-top:8px"><label class="wr18-field"><span>Location</span><select data-putaway="${x.id}"><option value="">Choose location</option>${S.locations.map(l=>`<option value="${l.id}" ${l.id===(x.current_location_id||x.warehouse_location_id)?'selected':''}>${esc(l.code)}${l.name?` · ${esc(l.name)}`:''}</option>`).join('')}</select></label></div></div>`).join('')}</div><div class="wr18-actions"><button class="wr18-primary" data-save-putaway>Save put-away</button></div>`}

function modal(title,body){const b=document.createElement('div'),m=document.createElement('div');b.className='wr18-modalback';m.className='wr18-modal';m.innerHTML=`<div class="wr18-modalhead"><h3>${esc(title)}</h3><button class="wr18-x">×</button></div>${body}`;document.body.append(b,m);const close=()=>{b.remove();m.remove()};b.onclick=close;m.querySelector('.wr18-x').onclick=close;return{m,close}}
function cargoPath(c){const out=[];let n=c;while(n){out.unshift(n);n=S.cargo.find(x=>x.id===n.parent_id)}return out}
function openCargo(id=null,parentId=null){const c=id?S.cargo.find(x=>x.id===id):null,p=parentId?S.cargo.find(x=>x.id===parentId):null,path=p?cargoPath(p):c?cargoPath(c).slice(0,-1):[],{m,close}=modal(c?'Edit cargo':p?'Add inside':'Add handling unit',`${path.length?`<div class="wr18-breadcrumb">${path.map((x,i)=>`<button data-jump="${x.id}">${esc(x.quantity)} ${esc(x.uom||x.package_type)}</button>${i<path.length-1?'<span>›</span>':''}`).join('')}${p?'<span>› New contents</span>':''}</div>`:''}<div class="wr18-fields"><label class="wr18-field"><span>Package type</span><select id="ce-type">${TYPES.map(x=>`<option ${x===(c?.package_type||'BOX')?'selected':''}>${x}</option>`).join('')}</select></label><label class="wr18-field"><span>Quantity</span><input id="ce-qty" type="number" min="0" step="any" value="${esc(c?.quantity??1)}"></label><label class="wr18-field" style="grid-column:1/-1"><span>Description</span><input id="ce-desc" value="${esc(c?.description||'')}" placeholder="Cargo description"></label><label class="wr18-field"><span>Part number</span><input id="ce-part" value="${esc(c?.part_number||'')}"></label><label class="wr18-field"><span>SKU</span><input id="ce-sku" value="${esc(c?.sku||'')}"></label><label class="wr18-field"><span>Lot</span><input id="ce-lot" value="${esc(c?.lot_number||'')}"></label><label class="wr18-field"><span>Serial</span><input id="ce-serial" value="${esc(c?.serial_number||'')}"></label><label class="wr18-field"><span>Gross weight</span><input id="ce-weight" type="number" step="any" value="${esc(c?.weight_lb||'')}"></label><label class="wr18-field"><span>Weight unit</span><select id="ce-wu"><option>LB</option><option>KG</option></select></label><label class="wr18-field"><span>Length</span><input id="ce-l" type="number" step="any" value="${esc(c?.length_in||'')}"></label><label class="wr18-field"><span>Width</span><input id="ce-w" type="number" step="any" value="${esc(c?.width_in||'')}"></label><label class="wr18-field"><span>Height</span><input id="ce-h" type="number" step="any" value="${esc(c?.height_in||'')}"></label><label class="wr18-field"><span>Dimension unit</span><select id="ce-du"><option>IN</option><option>CM</option></select></label></div><div class="wr18-metrics"><div class="wr18-metric"><small>UOM</small><b id="ce-uom">${esc(c?.uom||UOM[c?.package_type]||'BOX')}</b></div><div class="wr18-metric"><small>Volume</small><b id="ce-vol">—</b></div><div class="wr18-metric"><small>Chargeable</small><b id="ce-chg">—</b></div></div><div class="wr18-actions"><button class="wr18-primary" id="ce-save">${c?'Save changes':'Add cargo'}</button></div>`);m.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{close();openCargo(b.dataset.jump)});const calc=()=>{let l=Number(m.querySelector('#ce-l').value||0),w=Number(m.querySelector('#ce-w').value||0),h=Number(m.querySelector('#ce-h').value||0),wt=Number(m.querySelector('#ce-weight').value||0),q=Number(m.querySelector('#ce-qty').value||1);if(m.querySelector('#ce-du').value==='CM'){l/=2.54;w/=2.54;h/=2.54}if(m.querySelector('#ce-wu').value==='KG')wt*=2.2046226218;const ci=l*w*h*q,cbm=ci*0.000016387064,dim=ci/166;m.querySelector('#ce-vol').textContent=cbm?cbm.toFixed(3)+' m³':'—';m.querySelector('#ce-chg').textContent=Math.max(wt,dim)?Math.max(wt,dim).toFixed(1)+' lb':'—'};['#ce-l','#ce-w','#ce-h','#ce-weight','#ce-qty','#ce-wu','#ce-du'].forEach(s=>m.querySelector(s).oninput=calc);m.querySelector('#ce-type').onchange=e=>m.querySelector('#ce-uom').textContent=UOM[e.target.value]||'EA';calc();m.querySelector('#ce-save').onclick=async()=>{let wt=Number(m.querySelector('#ce-weight').value||0),l=Number(m.querySelector('#ce-l').value||0),w=Number(m.querySelector('#ce-w').value||0),h=Number(m.querySelector('#ce-h').value||0);if(m.querySelector('#ce-wu').value==='KG')wt*=2.2046226218;if(m.querySelector('#ce-du').value==='CM'){l/=2.54;w/=2.54;h/=2.54}const type=m.querySelector('#ce-type').value,payload={organization_id:S.wr.organization_id,job_id:S.wr.job_id,parent_id:c?.parent_id||p?.id||null,package_type:type,quantity:Number(m.querySelector('#ce-qty').value||1),uom:UOM[type]||'EA',description:m.querySelector('#ce-desc').value.trim()||null,part_number:m.querySelector('#ce-part').value.trim()||null,sku:m.querySelector('#ce-sku').value.trim()||null,lot_number:m.querySelector('#ce-lot').value.trim()||null,serial_number:m.querySelector('#ce-serial').value.trim()||null,weight_lb:wt||null,length_in:l||null,width_in:w||null,height_in:h||null,status:'received',processing_status:'processed',unloaded_quantity:Number(m.querySelector('#ce-qty').value||1),metadata:{input_weight_unit:m.querySelector('#ce-wu').value,input_dimension_unit:m.querySelector('#ce-du').value}};let q=c?supabase.from('cargo_units').update(payload).eq('id',c.id):supabase.from('cargo_units').insert(payload);const{error}=await q;if(error)return alert(error.message);close();await refresh();render();toast(c?'Cargo updated ✓':'Cargo added ✓')}}

async function saveParties(values){const c=exactEntity(values.customer),sh=exactEntity(values.shipper),co=exactEntity(values.consignee);if(!c)return alert('Choose an existing Customer entity.');await supabase.from('jobs').update({customer_id:c.id}).eq('id',S.job.id);for(const[r,v,e]of[['shipper',values.shipper,sh],['consignee',values.consignee,co]]){if(!String(v||'').trim())continue;const payload={organization_id:S.wr.organization_id,warehouse_receipt_id:S.wr.id,role:r,entity_id:e?.id||null,display_name:e?.name||String(v).trim(),phone:e?.phone||null,email:e?.email||null};const existing=party(r);if(existing)await supabase.from('warehouse_receipt_parties').update(payload).eq('id',existing.id);else await supabase.from('warehouse_receipt_parties').insert(payload)}await event('STEP_COMPLETED',{step_key:'parties'});await refresh();render();toast('Parties saved ✓')}
async function uploadFile(file,category='SCANNED_DOCUMENT'){const{data:tx,error:te}=await supabase.from('transactions').select('id').eq('transaction_type','WAREHOUSE_RECEIPT').eq('domain_record_id',S.wr.id).maybeSingle();if(te||!tx)throw te||new Error('Transaction record is missing.');const path=`${S.wr.organization_id}/${tx.id}/transaction/${crypto.randomUUID()}_${file.name}`;const{error:up}=await supabase.storage.from('nodara-documents').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up)throw up;const{error}=await supabase.rpc('nodara_register_document',{p_transaction_id:tx.id,p_document_type:'OTHER',p_storage_path:path,p_file_name:file.name,p_mime_type:file.type||'application/octet-stream',p_cargo_object_id:null,p_entity_id:null,p_template_id:null,p_display_name:file.name,p_document_number:null,p_category:category,p_link_role:'SUPPORTING',p_source:'USER',p_status:'ACTIVE',p_notes:null,p_metadata:{surface:'WR_V18'},p_provenance:{source_type:'USER',surface:'WR_V18'}});if(error)throw error;await refresh();render();toast('Document attached ✓')}

function render(){document.body.classList.add('wr18-active');main.style.visibility='visible';main.innerHTML=`<div class="wr18">${head()}${mode==='record'?record():`<div class="wr18-content">${guided()}</div>`}${datalist()}</div>`;bind()}
function bind(){main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});main.querySelectorAll('[data-out]').forEach(b=>b.onclick=()=>{const k=b.dataset.out;if(k==='pdf')window.NodaraWROutput?.warehouseReceiptPDF(S.wr.id);if(k==='4x6')window.NodaraWROutput?.labels4x6(S.wr.id);if(k==='2x1')window.NodaraWROutput?.labels2x1(S.wr.id)});main.querySelectorAll('[data-doc-upload]').forEach(b=>b.onclick=()=>{const i=document.createElement('input');i.type='file';i.accept='image/*,application/pdf';i.onchange=()=>i.files?.[0]&&uploadFile(i.files[0]).catch(e=>alert(e.message));i.click()});main.querySelectorAll('[data-doc-scan]').forEach(b=>b.onclick=()=>window.NodaraWRScanner?.open?window.NodaraWRScanner.open({category:'SCANNED_DOCUMENT'}):alert('Scanner is not ready.'));main.querySelectorAll('[data-party-more]').forEach(b=>b.onclick=()=>main.querySelector(`[data-partycard="${b.dataset.partyMore}"]`)?.classList.toggle('open'));main.querySelectorAll('[data-party-edit]').forEach(b=>b.onclick=()=>{mode='guided';const step=workflow().find(x=>x.key==='parties');if(step&&!done(step)){render()}else{tab='parties';openPartyEditor(b.dataset.partyEdit)}});main.querySelectorAll('[data-cargo-add]').forEach(b=>b.onclick=()=>openCargo());main.querySelectorAll('[data-cargo-edit]').forEach(b=>b.onclick=()=>openCargo(b.dataset.cargoEdit));main.querySelectorAll('[data-cargo-inside]').forEach(b=>b.onclick=()=>openCargo(null,b.dataset.cargoInside));main.querySelectorAll('[data-cargo-copy]').forEach(b=>b.onclick=()=>copyCargo(b.dataset.cargoCopy));main.querySelectorAll('[data-cargo-label]').forEach(b=>b.onclick=()=>window.NodaraWROutput?.labels4x6(S.wr.id,[b.dataset.cargoLabel]));main.querySelectorAll('[data-cargo-mini]').forEach(b=>b.onclick=()=>window.NodaraWROutput?.labels2x1(S.wr.id,[b.dataset.cargoMini]));main.querySelector('[data-g-checkin]')?.addEventListener('click',checkin);main.querySelector('[data-g-verify]')?.addEventListener('click',verify);main.querySelector('[data-g-start]')?.addEventListener('click',()=>dockStamp('operation_started_at','Unload started ✓'));main.querySelector('[data-g-finish]')?.addEventListener('click',finishUnload);main.querySelector('[data-g-release]')?.addEventListener('click',()=>dockStamp('time_out','Driver released ✓'));main.querySelector('[data-g-parties]')?.addEventListener('click',()=>saveParties({customer:main.querySelector('#g-customer').value,shipper:main.querySelector('#g-shipper').value,consignee:main.querySelector('#g-consignee').value}));main.querySelector('[data-r-arrival]')?.addEventListener('click',saveArrival);main.querySelector('[data-save-putaway]')?.addEventListener('click',savePutaway);main.querySelector('[data-g-complete]')?.addEventListener('click',completeWR);main.querySelector('[data-g-notify]')?.addEventListener('click',async()=>{await event('CUSTOMER_NOTIFIED',{channel:'manual'});await refresh();render();toast('Notification recorded ✓')});main.querySelectorAll('[data-skip]').forEach(b=>b.onclick=async()=>{await event('STEP_SKIPPED',{step_key:b.dataset.skip});await refresh();render();toast('Optional step skipped')});main.querySelectorAll('[data-g-generic]').forEach(b=>b.onclick=async()=>{await event('STEP_COMPLETED',{step_key:b.dataset.gGeneric});await refresh();render()});main.querySelector('[data-open-workflow]')?.addEventListener('click',()=>window.nodaraWorkflowStudio?.('WAREHOUSE_RECEIPT'));main.querySelector('[data-id-upload]')?.addEventListener('click',()=>{const i=document.createElement('input');i.type='file';i.accept='image/*,application/pdf';i.onchange=()=>i.files?.[0]&&uploadFile(i.files[0],'DRIVER_ID').catch(e=>alert(e.message));i.click()})}
function openPartyEditor(role){const label=role[0].toUpperCase()+role.slice(1),current=role==='customer'?customerName():party(role)?.display_name||'',{m,close}=modal(`Edit ${label}`,`<label class="wr18-field" style="margin-top:14px"><span>${label}</span><input id="pe-name" list="wr18-entities" value="${esc(current==='Unidentified customer'?'':current)}"></label>${datalist()}<div class="wr18-actions"><button class="wr18-primary" id="pe-save">Save</button></div>`);m.querySelector('#pe-save').onclick=async()=>{const v=m.querySelector('#pe-name').value,e=exactEntity(v);if(!e)return alert('Choose an existing entity.');if(role==='customer')await supabase.from('jobs').update({customer_id:e.id}).eq('id',S.job.id);else{const old=party(role),payload={organization_id:S.wr.organization_id,warehouse_receipt_id:S.wr.id,role,entity_id:e.id,display_name:e.name,phone:e.phone||null,email:e.email||null};if(old)await supabase.from('warehouse_receipt_parties').update(payload).eq('id',old.id);else await supabase.from('warehouse_receipt_parties').insert(payload)}close();await refresh();render();toast(`${label} updated ✓`)}}
async function copyCargo(id){const c=S.cargo.find(x=>x.id===id);if(!c)return;const clone={...c};delete clone.id;delete clone.created_at;delete clone.updated_at;clone.handling_unit_code=null;clone.uin=null;const{data:newRoot,error}=await supabase.from('cargo_units').insert(clone).select().single();if(error)return alert(error.message);for(const k of children(id)){const q={...k,parent_id:newRoot.id};delete q.id;delete q.created_at;delete q.updated_at;q.handling_unit_code=null;q.uin=null;await supabase.from('cargo_units').insert(q)}await refresh();render();toast('Handling unit copied ✓')}
async function checkin(){const carrier=main.querySelector('#g-carrier').value.trim(),driver=main.querySelector('#g-driver').value.trim(),ref=main.querySelector('#g-ref').value.trim(),door=main.querySelector('#g-door').value.trim(),ent=exactEntity(carrier),payload={organization_id:S.wr.organization_id,warehouse_receipt_id:S.wr.id,direction:'inbound',carrier_id:ent?.id||null,carrier_name_snapshot:carrier||null,driver_name:driver||null,door:door||null,bol_number:ref||null,time_in:new Date().toISOString()};if(S.visit)await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id);else await supabase.from('warehouse_visits').insert(payload);await refresh();render();toast('Checked in · '+tm(S.visit?.time_in||new Date()))}
async function verify(){if(!main.querySelector('#g-verify')?.checked)return alert('Confirm the verification statement first.');const now=new Date().toISOString();await supabase.from('warehouse_visits').update({driver_id_verified:true,driver_id_verified_at:now,driver_id_verified_by:await userId()}).eq('id',S.visit.id);await refresh();render();toast('Driver verified ✓')}
async function dockStamp(field,msg){await supabase.from('warehouse_visits').update({[field]:new Date().toISOString()}).eq('id',S.visit.id);await refresh();render();toast(msg)}
async function finishUnload(){await supabase.from('warehouse_visits').update({unload_expected_qty:Number(main.querySelector('#g-exp').value||0)||null,unload_actual_qty:Number(main.querySelector('#g-act').value||0)||null,unload_uom:main.querySelector('#g-uom').value,operation_completed_at:new Date().toISOString()}).eq('id',S.visit.id);await supabase.from('warehouse_receipts').update({received_at:new Date().toISOString()}).eq('id',S.wr.id);await refresh();render();toast('Unload finished ✓')}
async function saveArrival(){const carrier=main.querySelector('#r-carrier').value.trim(),ent=exactEntity(carrier),pro=main.querySelector('#r-pro').value.trim(),tr=main.querySelector('#r-trailer').value.split('/').map(x=>x.trim());await supabase.from('warehouse_visits').update({carrier_id:ent?.id||null,carrier_name_snapshot:carrier||null,driver_name:main.querySelector('#r-driver').value.trim()||null,bol_number:main.querySelector('#r-bol').value.trim()||null,pro_number:pro||null,door:main.querySelector('#r-door').value.trim()||null,trailer_number:tr[0]||null,seal_number:tr[1]||null}).eq('id',S.visit.id);await refresh();render();toast('Arrival saved ✓')}
async function savePutaway(){for(const s of main.querySelectorAll('[data-putaway]'))if(s.value)await supabase.from('cargo_units').update({current_location_id:s.value,warehouse_location_id:s.value}).eq('id',s.dataset.putaway);await refresh();render();toast('Put-away saved ✓')}
async function completeWR(){const hard=missing().filter(x=>!String(x).startsWith('Driver on site'));if(hard.length)return alert('Complete these items first: '+hard.join(', '));const now=new Date().toISOString();await supabase.from('warehouse_receipts').update({status:'completed',completed_at:now,received_at:S.wr.received_at||now,processing_status:'completed'}).eq('id',S.wr.id);await event('STEP_COMPLETED',{step_key:'complete'});await refresh();render();toast('WR completed ✓')}

export async function mountWarehouseReceiptV18(id,{mode:nextMode='guided'}={}){wrId=id;mode=nextMode;tab='overview';await load(id);render()}
export function enhanceNewReceivingV18(){/* new receiving remains intentionally minimal; canonical ownership starts as soon as a WR shell exists */}
window.nodaraMountWRV18=mountWarehouseReceiptV18;
